"""Create a portable HTML evidence viewer from the existing API trial, offline."""
import base64
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
RUN = HERE / '20260913T063904367636Z'
r = json.loads((RUN / 'result.json').read_text())
m = json.loads((RUN / 'manifest.json').read_text())
video = Path(m['video']).read_bytes()
assert hashlib.sha256(video).hexdigest() == m['video_sha256']
frames = []
for f in m['frames']:
    raw = (RUN / f['file']).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == f['sha256']
    frames.append({**f, 'src':'data:image/jpeg;base64,'+base64.b64encode(raw).decode()})
data = {'result':r,'frames':frames,'duration':6.37,'notes':[
    {'title':'Multiple balls are visible together', 'times':[2.1,2.3,2.6],
     'claim':'The API describes one persistent wooden sphere and assigns all its events to that identity.',
     'observation':'At 2.1 s, two wooden balls are visible simultaneously. This challenges the single-ball interpretation. Their paths need separate tracking before assigning events.',
     'event':'sustained_contact'},
    {'title':'Check the continuous-contact claim', 'times':[1.4,1.7,1.9,2.1,2.3],
     'claim':'The API labels sustained ring–sphere contact observed throughout 1.1–2.3 s.',
     'observation':'At 1.9 s, a ball appears above and visibly separated from the ring. At 2.1 s there are two balls. These frames challenge continuous contact for one tracked ball; they do not establish exact 3D contact or release times.',
     'event':'sustained_contact'},
    {'title':'Rebound needs a tracked trajectory', 'times':[2.3,2.4,2.6,2.8,2.9],
     'claim':'The API labels rebound observed at 2.4–2.9 s, while its first-contact and release claims are uncertain.',
     'observation':'Compare each ball separately across these frames. The response does not establish which ball reverses direction or distinguish a bounce from ring-driven transport. This is an unresolved interpretation, not a verified rebound.',
     'event':'rebound'}]}
template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>C.mp4 — Scene event review</title><style>
:root{color-scheme:dark;--bg:#10151d;--card:#1a2230;--line:#334155;--ink:#edf3fc;--muted:#adbdcf;--blue:#85caff;--amber:#f7cc80}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header,main,footer{max-width:1500px;margin:auto;padding:24px}h1{font-size:30px;letter-spacing:-.7px;margin:4px 0}h2{font-size:20px;margin:0 0 14px}h3{font-size:16px;margin:0 0 8px}p{margin:8px 0 16px}button,select,input{font:inherit}button,select{background:#253248;color:var(--ink);border:1px solid #4b6079;border-radius:8px;padding:8px 12px;cursor:pointer}button:hover{background:#354964}button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid var(--blue);outline-offset:3px}button[aria-pressed=true]{background:#204969;border-color:var(--blue)}button:disabled{opacity:.45;cursor:default}.eyebrow{color:var(--blue);text-transform:uppercase;letter-spacing:2px;font-size:12px}.muted,small{color:var(--muted)}.pills,.controls,.tabs{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.pill{border:1px solid var(--line);border-radius:20px;padding:4px 10px;font-size:12px}.notice{border-left:3px solid var(--amber);padding:12px 16px;background:#29271f;border-radius:4px}.layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:24px}.panel{background:var(--card);border:1px solid var(--line);padding:18px;border-radius:14px;margin-bottom:18px}.viewer{position:sticky;top:16px;align-self:start}video{display:block;width:100%;border-radius:9px;background:#000}input[type=range]{width:100%;accent-color:var(--blue)}.readout{font-variant-numeric:tabular-nums;font-weight:650}.tabs button{font-size:13px}.status{font-size:12px;border:1px solid var(--line);padding:3px 8px;border-radius:15px;white-space:nowrap}.observed{color:#a5e2ce}.uncertain{color:var(--amber)}.not_observed{color:var(--muted)}.titlebar{display:flex;align-items:center;gap:8px;justify-content:space-between;margin:18px 0 8px}.interval{padding:12px;border:1px solid var(--line);border-radius:10px;margin:12px 0}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.frame{padding:0;overflow:hidden;text-align:left;background:#111925;border-color:var(--line)}.frame img{width:100%;display:block;aspect-ratio:16/9}.frame span{display:block;padding:5px 8px;font-size:12px}.frame.active{border:2px solid var(--blue)}.bigframe{width:100%;border-radius:8px;display:block;margin-top:12px}.trackrow{display:grid;grid-template-columns:130px 1fr;gap:10px;align-items:center;margin:9px 0}.tracklabel{padding:4px;text-align:left;font-size:12px;background:transparent;border:0}.track{position:relative;height:24px;background:#101722;border-radius:5px;overflow:hidden}.segment{position:absolute;height:100%;background:#487b9d;border:1px solid #85caff;border-radius:4px;padding:0;min-width:3px}.segment.uncertain{background:#876c35;border-color:var(--amber)}.playhead{position:absolute;width:2px;height:100%;background:white;pointer-events:none}.empty{font-size:11px;padding-left:8px;color:var(--muted)}.ticks{display:flex;justify-content:space-between;margin-left:140px;color:var(--muted);font-size:11px}.note{border-left:3px solid var(--amber)}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:400px;overflow:auto}details{margin-top:18px}a{color:var(--blue)}#allframes{grid-template-columns:repeat(5,minmax(0,1fr))}dialog{background:var(--card);color:var(--ink);border:1px solid var(--line);border-radius:12px;width:min(1000px,95vw);padding:18px}dialog::backdrop{background:#000b}dialog img{width:100%;display:block}footer{font-size:12px;color:var(--muted)}@media(max-width:960px){.layout{grid-template-columns:1fr}.viewer{position:static}#allframes{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:520px){header,main,footer{padding:14px}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.trackrow{grid-template-columns:100px 1fr}.ticks{margin-left:110px}h1{font-size:25px}}
</style></head><body><header><div class="eyebrow">SceneScore / visual evidence</div><h1>C.mp4 — inspect the event proposals</h1>
<p class="muted">One API trial, with the exact frames it received. Click an event or frame to inspect the source moment.</p>
<div class="pills"><span class="pill">6.37 s video</span><span class="pill">64 frames · 10 fps</span><span class="pill">GPT-4.1 mini · live API</span><span class="pill">No audio analysis</span><span class="pill" id="cost"></span></div>
<p class="notice"><strong>Proposals for your review.</strong> “Observed” is the API model’s label, not verified truth. My review notes are based on inspecting selected frames; no independent labels or 3D geometry are available.</p></header>
<main><div class="layout"><section class="viewer"><div class="panel"><h2>Source video</h2><video id="video" controls playsinline preload="metadata" src="__VIDEO__"></video>
<div class="controls" style="margin-top:12px"><button id="previous">← Previous sample</button><button id="next">Next sample →</button><span class="readout" id="time">0.000 s</span><label>Speed <select id="speed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option></select></label></div>
<label for="scrub" class="muted">Inspect sampled frames</label><input id="scrub" type="range" min="0" max="63" step="1" value="0">
<div class="controls"><span id="samplelabel" class="readout"></span><button id="enlarge">Enlarge sampled frame</button></div><img id="sample" class="bigframe" alt="Selected sampled video frame">
<p class="muted"><small>The sampled still is the nearest API input frame. The video can show motion between the 0.1 s samples.</small></p></div>
<div class="panel"><h2>API event timeline</h2><p class="muted"><small>Bars reproduce the model’s proposed intervals. Thin bars may bracket uncertain onset rather than event duration.</small></p><div id="timeline"></div><div class="ticks"><span>0 s</span><span>2 s</span><span>4 s</span><span>6.37 s</span></div></div></section>
<section><div class="panel"><h2>What the API proposed</h2><div id="tabs" class="tabs"></div><div id="event"></div><details><summary>Model summary and object identities</summary><p id="modelsummary"></p><pre id="objects"></pre></details></div>
<h2>My review notes — inspect the evidence</h2><div id="notes"></div></section></div>
<section class="panel"><h2>All 64 input frames</h2><p class="muted">Click a frame to pause the video at its timestamp. Use the enlarged view above to inspect detail.</p><div id="allframes" class="gallery"></div></section>
<section class="panel"><h2>Provenance and exact response</h2><div id="metadata"></div><button id="download">Download API result JSON</button><details><summary>Exact model response</summary><pre id="raw"></pre></details><details><summary>Exact prompt sent with the frames</summary><pre id="prompt"></pre></details><details><summary>Frame timestamps and hashes</summary><pre id="hashes"></pre></details></section></main>
<footer>Local, self-contained report. Source video and sampled images are embedded. Opening it makes no API calls. No app markers were inserted or music executed.</footer>
<dialog id="lightbox"><div class="controls" style="justify-content:space-between;margin-bottom:12px"><strong id="lighttitle"></strong><button id="close">Close</button></div><img id="lightimage" alt="Enlarged sampled frame"><p class="muted">This is the 768 × 432 image supplied to the API, not the full-resolution video.</p></dialog>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';
const D=JSON.parse(document.getElementById('data').textContent), R=D.result, F=D.frames, A=R.analysis.assessments;
const $=id=>document.getElementById(id), video=$('video');let current=0,selected='approach',stopAt=null;
const title=s=>s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());
const el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;};
function nearest(t){let best=0;for(let i=1;i<F.length;i++)if(Math.abs(F[i].timestamp_s-t)<Math.abs(F[best].timestamp_s-t))best=i;return best;}
function update(t){current=nearest(t);const f=F[current];$('scrub').value=current;$('time').textContent=t.toFixed(3)+' s';$('samplelabel').textContent='Sample '+(current+1)+' / '+F.length+' · '+f.timestamp_s.toFixed(1)+' s';$('sample').src=f.src;$('sample').alt='API input frame at '+f.timestamp_s.toFixed(1)+' seconds';$('previous').disabled=current===0;$('next').disabled=current===F.length-1;document.querySelectorAll('.playhead').forEach(x=>x.style.left=(t/D.duration*100)+'%');document.querySelectorAll('.frame').forEach(x=>x.classList.toggle('active',Number(x.dataset.index)===current));}
function seek(t){stopAt=null;video.pause();video.currentTime=t;update(t);}
function gallery(times){const g=el('div',undefined,'gallery');times.forEach(t=>{const i=nearest(t),f=F[i],b=el('button',undefined,'frame');b.dataset.index=i;b.title='Inspect '+f.timestamp_s.toFixed(1)+' seconds';const img=el('img');img.src=f.src;img.alt='Video frame at '+f.timestamp_s.toFixed(1)+' seconds';img.loading='lazy';b.append(img,el('span',f.timestamp_s.toFixed(1)+' s'));b.onclick=()=>seek(f.timestamp_s);g.append(b);});return g;}
function choose(key,jump=true){selected=key;document.querySelectorAll('#tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.key===key)));const a=A[key],box=$('event');box.replaceChildren();const heading=el('div',undefined,'titlebar');heading.append(el('h3',title(key)),el('span','Model: '+a.status.replaceAll('_',' '),'status '+a.status));box.append(heading,el('p',a.reason));if(!a.intervals.length)box.append(el('p','No timestamp proposed. This does not establish that the event is absent.','muted'));
a.intervals.forEach(iv=>{const c=el('div',undefined,'interval'),row=el('div',undefined,'controls'),b=el('button',iv.start_s.toFixed(1)+'–'+iv.end_s.toFixed(1)+' s · Inspect');b.onclick=()=>seek(iv.start_s);const play=el('button','Play interval slowly');play.onclick=()=>{video.pause();video.currentTime=Math.max(0,iv.start_s-.2);video.playbackRate=.25;$('speed').value='.25';$('speed').value='0.25';stopAt=Math.min(D.duration,iv.end_s+.2);video.play().catch(()=>{stopAt=null;});};row.append(b,play);c.append(row,el('p','Model object IDs: '+iv.object_ids.join(', '),'muted'),el('p',iv.explanation),el('h3','Frames cited by the API'),gallery(iv.evidence_timestamps_s));box.append(c);});if(jump&&a.intervals.length)seek(a.intervals[0].start_s);}
Object.keys(A).forEach(key=>{const b=el('button',title(key));b.dataset.key=key;b.setAttribute('aria-pressed','false');b.onclick=()=>choose(key);$('tabs').append(b);const row=el('div',undefined,'trackrow'),label=el('button',title(key),'tracklabel');label.onclick=()=>choose(key);const track=el('div',undefined,'track');A[key].intervals.forEach(iv=>{const seg=el('button',undefined,'segment '+A[key].status);seg.style.left=iv.start_s/D.duration*100+'%';seg.style.width=(iv.end_s-iv.start_s)/D.duration*100+'%';seg.title=title(key)+': '+iv.start_s+'–'+iv.end_s+' s';seg.setAttribute('aria-label',seg.title);seg.onclick=()=>{choose(key,false);seek(iv.start_s);};track.append(seg);});if(!A[key].intervals.length)track.append(el('span','No proposal','empty'));track.append(el('div',undefined,'playhead'));row.append(label,track);$('timeline').append(row);});
D.notes.forEach(n=>{const c=el('article',undefined,'panel note');c.append(el('h3',n.title),el('p','API claim: '+n.claim),el('p','My visual review: '+n.observation),gallery(n.times));const b=el('button','Compare '+title(n.event)+' proposal');b.style.marginTop='12px';b.onclick=()=>{choose(n.event,false);seek(n.times[0]);};c.append(b);$('notes').append(c);});
$('allframes').replaceWith(Object.assign(gallery(F.map(f=>f.timestamp_s)),{id:'allframes'}));
$('modelsummary').textContent=R.analysis.summary;$('objects').textContent=JSON.stringify(R.analysis.objects,null,2);
$('raw').textContent=R.text;$('prompt').textContent=R.prompt;$('hashes').textContent=JSON.stringify(F.map(({src,...f})=>f),null,2);
const cost=(R.usage.input_tokens*.4+R.usage.output_tokens*1.6)/1e6;$('cost').textContent='Estimated API cost $'+cost.toFixed(4);
$('metadata').append(el('p','Model: '+R.model+' · HTTP '+R.http_status+' · '+R.elapsed_seconds+' s API latency'),el('p',R.usage.input_tokens.toLocaleString()+' input + '+R.usage.output_tokens.toLocaleString()+' output tokens. Cost is an estimate at $0.40 / million input and $1.60 / million output; account balance was not checked.'),el('p','Video SHA-256: '+R.video_sha256,'muted'),el('p','Run UTC: '+R.utc+' · Source: C.mp4 · Audio not analyzed.','muted'));
const rates=el('a','Published model rates');rates.href='https://developers.openai.com/api/docs/models/gpt-4.1-mini';$('metadata').append(rates);
$('download').onclick=()=>{const blob=new Blob([JSON.stringify(R,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='C-video-api-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('previous').onclick=()=>seek(F[Math.max(0,current-1)].timestamp_s);$('next').onclick=()=>seek(F[Math.min(F.length-1,current+1)].timestamp_s);$('scrub').oninput=e=>seek(F[Number(e.target.value)].timestamp_s);$('speed').onchange=e=>video.playbackRate=Number(e.target.value);
video.ontimeupdate=()=>{if(stopAt!==null&&video.currentTime>=stopAt){video.pause();stopAt=null;}update(video.currentTime);};video.onloadedmetadata=()=>update(video.currentTime);video.onseeked=()=>update(video.currentTime);
$('enlarge').onclick=()=>{$('lightimage').src=F[current].src;$('lighttitle').textContent='Sample at '+F[current].timestamp_s.toFixed(1)+' seconds';$('lightbox').showModal();};$('close').onclick=()=>$('lightbox').close();
choose('approach',false);update(0);
</script></body></html>'''
html = template.replace('__VIDEO__','data:video/mp4;base64,'+base64.b64encode(video).decode()).replace('__DATA__',json.dumps(data).replace('<','\\u003c'))
destination=HERE / 'C-video-report.html'
destination.write_text(html,encoding='utf-8')
print(json.dumps({'report':str(destination),'bytes':destination.stat().st_size,'embedded_frames':len(frames),'video_hash_verified':True}))
